namespace Acme.Router;

public sealed class RouteId : IEquatable<RouteId>
{
	public string Value { get; }

	private RouteId(string value) => Value = value;

	public static RouteId Create(string value)
	{
		var v = (value ?? "").Trim();
		if (v.Length == 0) throw new ArgumentException("ROUTE_ID_EMPTY");
		if (v.Length > 32) throw new ArgumentException("ROUTE_ID_TOO_LONG");
		return new RouteId(v);
	}

	public bool Equals(RouteId? other) =>
		other is not null && string.Equals(Value, other.Value, StringComparison.OrdinalIgnoreCase);

	public override bool Equals(object? obj) => Equals(obj as RouteId);

	public override int GetHashCode() => StringComparer.OrdinalIgnoreCase.GetHashCode(Value);

	public static bool operator ==(RouteId? a, RouteId? b) => a is null ? b is null : a.Equals(b);

	public static bool operator !=(RouteId? a, RouteId? b) => !(a == b);

	public override string ToString() => Value;
}

namespace Acme.Router;

public sealed class Route
{
	private static readonly string[] Methods = ["GET", "POST", "PUT", "DELETE"];

	public RouteId Id { get; }
	public string Method { get; }
	public string Path { get; }
	public int Priority { get; }

	public Route(RouteId id, string method, string path, int priority = 0)
	{
		var m = (method ?? "").Trim().ToUpperInvariant();
		if (!Methods.Contains(m)) throw new ArgumentException("METHOD_NOT_SUPPORTED");
		if (string.IsNullOrEmpty(path) || path[0] != '/') throw new ArgumentException("PATH_INVALID");
		if (priority < 0) throw new ArgumentOutOfRangeException(nameof(priority));
		Id = id;
		Method = m;
		Path = NormalizePath(path);
		Priority = priority;
	}

	internal static string NormalizePath(string path)
	{
		var p = (path ?? "").Trim();
		if (p.Length <= 1) return p;
		var trimmed = p.TrimEnd('/');
		return trimmed.Length == 0 ? "/" : trimmed;
	}
}

namespace Acme.Router;

public static class RoutePattern
{
	private static bool IsParam(string segment) =>
		segment.Length > 2 && segment[0] == '{' && segment[^1] == '}';

	private static string[] Split(string path) => (path ?? "").Trim('/').Split('/');

	public static bool IsParametric(string pattern) => Split(pattern).Any(IsParam);

	public static bool TryMatch(string pattern, string path, out IReadOnlyDictionary<string, string> values)
	{
		values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		var p = Split(pattern);
		var s = Split(path);
		if (p.Length != s.Length) return false;
		var found = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		for (var i = 0; i < p.Length; i++)
		{
			if (IsParam(p[i]))
			{
				if (s[i].Length == 0) return false;
				found[p[i][1..^1]] = s[i];
			}
			else if (!string.Equals(p[i], s[i], StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
		}
		values = found;
		return true;
	}
}

namespace Acme.Router;

public sealed record RouteMatch(Route Route, IReadOnlyDictionary<string, string> Values);

public sealed class RouteTable
{
	private readonly List<Route> _routes = [];

	public int Count => _routes.Count;

	public void Add(Route route)
	{
		if (_routes.Any(r => r.Method == route.Method && string.Equals(r.Path, route.Path, StringComparison.OrdinalIgnoreCase)))
			throw new InvalidOperationException("DUPLICATE_ROUTE");
		if (_routes.Any(r => r.Id == route.Id))
			throw new InvalidOperationException("DUPLICATE_ID");
		_routes.Add(route);
	}

	private IEnumerable<Route> Literal(string method, string path)
	{
		var p = Route.NormalizePath(path);
		return _routes.Where(r =>
			!RoutePattern.IsParametric(r.Path)
			&& string.Equals(r.Method, method, StringComparison.OrdinalIgnoreCase)
			&& string.Equals(r.Path, p, StringComparison.OrdinalIgnoreCase));
	}

	public Route? Match(string method, string path) => Literal(method, path).FirstOrDefault();

	public RouteMatch? Resolve(string method, string path)
	{
		var literal = Literal(method, path).OrderByDescending(r => r.Priority).FirstOrDefault();
		if (literal is not null) return new RouteMatch(literal, new Dictionary<string, string>());
		var candidates = _routes
			.Where(r => RoutePattern.IsParametric(r.Path) && string.Equals(r.Method, method, StringComparison.OrdinalIgnoreCase))
			.OrderByDescending(r => r.Priority);
		foreach (var r in candidates)
		{
			if (RoutePattern.TryMatch(r.Path, path, out var values)) return new RouteMatch(r, values);
		}
		return null;
	}
}
